```json
{
  "root_causes": [
    {
      "service": "ts-user-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH j AS (SELECT 'abn' p, c.service_name caller, s.service_name callee, (CAST(c.duration AS DOUBLE)-CAST(s.duration AS DOUBLE))/1e6 gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' UNION ALL SELECT 'norm', c.service_name, s.service_name, (CAST(c.duration AS DOUBLE)-CAST(s.duration AS DOUBLE))/1e6 FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server') SELECT p, caller, callee, count(*) n, approx_quantile(gap_ms,0.5) gap_med, approx_quantile(gap_ms,0.95) gap_p95, max(gap_ms) gap_max FROM j WHERE caller='ts-user-service' AND callee='ts-auth-service' GROUP BY 1,2,3 ORDER BY 1",
          "claim": "ts-user to ts-auth calls: client-minus-server gap median ~1ms normally but p95 ~640ms (max 645ms) in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT CAST(c.time AS VARCHAR) t, round(c.duration/1e6,1) client_ms, round(s.duration/1e6,1) server_ms, round((c.duration-s.duration)/1e6,1) gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-user-service' AND c.span_name='POST' ORDER BY c.time",
          "claim": "Sporadic ts-user POST calls to auth take 282-720ms client-side while auth server span stays about 75ms, so time is lost before the server sees the request."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) med_ms, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name='AuthController.createDefaultUser' GROUP BY 1,2,3",
          "claim": "ts-auth createDefaultUser median stays about 74ms, p95 rises to about 280ms in the abnormal period (normal p95 about 75ms)."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, approx_quantile(c.duration/1e6,0.95) client_p95_ms, approx_quantile(s.duration/1e6,0.95) server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-user-service' AND c.span_name='POST' GROUP BY 1,2",
          "claim": "ts-user's client POST to ts-auth has p95 far above the auth server span p95, showing the delay sits on the ts-user to ts-auth path."
        }
      ]
    },
    {
      "from": "ts-user-service",
      "to": "ts-admin-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-user-service' AND span_name IN ('UserController.registerUser','POST /api/v1/userservice/users/register') GROUP BY 1,2",
          "claim": "ts-user register handler p95 rises to hundreds of milliseconds in the abnormal period, driven by the slow auth call."
        }
      ]
    },
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2",
          "claim": "User-facing POST /api/v1/adminuserservice/users at ts-ui-dashboard and ts-admin-user-service both show p95 about 300ms in the abnormal period."
        }
      ]
    }
  ]
}
```

